// ─── Quality: a day of scores, and the judge's call on one failing run ──────

const THRESHOLD = 0.7;

// Runs scatter through the day. Most score high; a cluster dips under the
// threshold late morning, and one of those is the run the judge card shows.
const RUNS = Array.from({ length: 56 }, (_, i) => {
  const x = (i + 0.5) / 56;
  const dip = x > 0.3 && x < 0.48 && noise(i, 31) < 0.7;
  const base = dip ? 0.38 + 0.26 * noise(i, 32) : 0.74 + 0.24 * noise(i, 33);
  return { x, y: Math.min(0.99, base) };
});
const PICK = RUNS.reduce((lo, r, i) => (r.y < RUNS[lo]!.y ? i : lo), 0);
RUNS[PICK]!.y = 0.32;
RUNS[PICK]!.x = 0.55;

const HOURS = ["00:00", "06:00", "12:00", "18:00"];

const BAD_REPLY =
  "Your order is processing. Orders can take time. Please wait and check back later.";

// The quality figure tells its story in order: the day's runs land left to
// right, the failing run gets its ring, and the judge card slides in from the
// left with the verdict. The threshold line is part of the chart and stays
// put. About a second in all.
const DOTS = 0.5; // the runs land over this long
const PICK_AT = DOTS + 0.3;
const JUDGE_AT = PICK_AT + 0.15;

export function QualityReview() {
  const passed = RUNS.filter((r) => r.y >= THRESHOLD).length;
  const { shown } = useReveal();
  const on = { opacity: shown ? 1 : 0 };
  return (
    <div className="flex flex-col gap-4 sm:block">
      <Scene>
        <CardHeader className="flex flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-2">
            <CheckChip presetId="helpfulness" className="size-4.5" />
            <CardTitle>Helpfulness</CardTitle>
          </div>
          <div className="flex items-center gap-3 text-xs  tabular-nums">
            <span className="text-muted-foreground">{RUNS.length} scored</span>
            <span>{Math.round((passed / RUNS.length) * 100)}% pass</span>
          </div>
        </CardHeader>
        <CardContent>
          <div className="mt-5 pb-3 grid grid-cols-[1.7rem_1fr] grid-rows-[1fr_1.25rem] gap-x-2">
            <div className="relative text-[11px] text-muted-foreground tabular-nums mr-2">
              {[1, 0.5, 0].map((v) => (
                <span
                  key={v}
                  className="absolute right-0 -translate-y-1/2"
                  style={{ top: `${(1 - v) * 100}%` }}
                >
                  {v.toFixed(1)}
                </span>
              ))}
            </div>
            <div className="relative h-60 border-b border-border/50">
              <span
                aria-hidden
                className="absolute inset-x-0 top-1/2 border-t border-border/50"
              />
              <span
                aria-hidden
                className="absolute inset-x-0 border-t border-dashed mt-1.5 dark:border-neutral-700 border-neutral-300"
                style={{ top: `${(1 - THRESHOLD) * 100}%` }}
              />
              <span
                className="absolute right-0 pt-3.5 text-[10px] font-medium text-red-500 tabular-nums"
                style={{ top: `${(1 - THRESHOLD) * 100}%` }}
              >
                {THRESHOLD.toFixed(2)}
              </span>
              {RUNS.map((r, i) => {
                const pass = r.y >= THRESHOLD;
                const picked = i === PICK;
                return (
                  // Motion owns the transform, so the centering translate
                  // rides along with the scale instead of a utility class.
                  <motion.span
                    key={r.x}
                    className={cn(
                      "absolute rounded-full ring-2 ring-card",
                      pass ? "bg-emerald-500" : "bg-red-500",
                      picked
                        ? "size-3.5 ring-rose-500 ring-offset-3 ring-offset-card"
                        : "size-2"
                    )}
                    initial={false}
                    animate={{ ...on, scale: shown ? 1 : 0, x: "-50%", y: "-50%" }}
                    transition={{
                      duration: 0.25,
                      ease: EASE,
                      delay: picked ? PICK_AT : r.x * DOTS,
                    }}
                    style={{
                      left: `${r.x * 100}%`,
                      top: `${(1 - r.y) * 100}%`,
                    }}
                  />
                );
              })}
            </div>
            <span />
            <div className="relative text-[11px] text-muted-foreground tabular-nums mt-2">
              {HOURS.map((h, i) => (
                <span
                  key={h}
                  className={cn("absolute top-1", i > 0 && "-translate-x-1/2")}
                  style={{ left: `${(i / HOURS.length) * 100}%` }}
                >
                  {h}
                </span>
              ))}
            </div>
          </div>
        </CardContent>
      </Scene>
      {/* On phones the card rides up over the chart so its top edge clips the
          flagged point, tying the two together; the bleed past the right
          edge is desktop only, since it would widen the page. */}
      <motion.div
        className="relative z-10 max-sm:-mt-35 max-sm:ml-10 sm:-mt-46 sm:-mr-10 sm:ml-auto sm:w-[44%]"
        initial={false}
        animate={{ ...on, x: shown ? 0 : -16 }}
        transition={{ duration: 0.6, ease: EASE, delay: JUDGE_AT }}
      >
        <Scene className="shadow-(--custom-shadow-lifted)">
          <CardHeader className="flex flex-row items-center justify-between gap-4">
            <div className="flex items-center gap-2">
              <CheckChip presetId="helpfulness" className="size-4.5" />
              Judge
            </div>
            <div className="flex items-center gap-3 text-sm">
              <Badge variant="red">
                <IconForbid2Filled className="mb-px" />
                Fail
              </Badge>
            </div>
          </CardHeader>
          <CardContent className="flex flex-col gap-4 mt-2">
            <div className="rounded-lg squircle:rounded-xl border border-dashed px-3 py-2">
              <span className="inline-flex items-center gap-1.5 text-xs text-muted-foreground">
                <IconScaleFilled className="mb-px size-3 shrink-0" />
                Judge’s reason
              </span>
              <p className="mt-1 text-[13px] leading-relaxed">
                Restates the status without checking the order. Gives no reason
                for the delay and no next step.
              </p>
            </div>
            <div className="flex gap-1.5">
              <div
                className={cn(
                  "flex size-5 shrink-0 mt-0.75 items-center justify-center rounded-full bg-muted-foreground/15 text-muted-foreground shadow-(--custom-shadow)"
                )}
              >
                <ClaudeLogo className="size-3" />
              </div>
              <p className="min-w-0 flex-1 px-1 text-sm leading-relaxed">
                {BAD_REPLY}
              </p>
            </div>
          </CardContent>
        </Scene>
      </motion.div>
    </div>
  );
}

