type TooltipProps = {
	variant?: TooltipVariant; // visual style of the tooltip surface
	roundness?: TooltipRoundness; // border-radius of the tooltip
	defaultIndex?: number; // data index shown by default with no hover
	cursor?: boolean; // whether the vertical cursor line follows the pointer
	// Formats the tooltip's heading (the x value), e.g. a raw bucket → a date.
	labelFormatter?: ComponentProps<typeof ChartTooltipContent>["labelFormatter"];
	// Formats each row's numeric value, e.g. raw ms → "1.70s".
	valueFormatter?: ComponentProps<typeof ChartTooltipContent>["valueFormatter"];
	// Lists the rows in reverse series order (top series first).
	reverse?: ComponentProps<typeof ChartTooltipContent>["reverse"];
};

/**
 * The hover tooltip. Reads the chart's selection from context so its content
 * dims unselected series. Hidden automatically while the chart is loading.
 */
export function Tooltip({
	variant,
	roundness,
	defaultIndex,
	cursor = true,
	labelFormatter,
	valueFormatter,
	reverse,
}: TooltipProps) {
	const { isLoading, selectedDataKey, syncId, isMouseInChart } = useLineChart();

	if (isLoading) return null;

	return (
		<ChartTooltip
			defaultIndex={defaultIndex}
			cursor={
				cursor ? { strokeDasharray: "3 3", strokeWidth: STROKE_WIDTH } : false
			}
			content={
				<ChartTooltipContent
					selected={selectedDataKey}
					roundness={roundness}
					variant={variant}
					labelFormatter={labelFormatter}
					valueFormatter={valueFormatter}
					reverse={reverse}
					// Synced peers draw the shared cursor line but stay quiet — only
					// the chart under the pointer shows tooltip content.
					hidden={syncId != null && !isMouseInChart}
				/>
			}
		/>
	);
}

type ThresholdProps = {
	value: number; // y value the line sits at, in the chart's y units
	label?: string; // small caption rendered inside the chart's right edge
	color?: string; // stroke + label color
};

/**
 * A horizontal reference line marking a configured alert threshold. The y-domain
 * extends to keep it visible when the threshold sits above the data.
 */
export function Threshold({
	value,
	label,
	color = "var(--destructive)",
}: ThresholdProps) {
	const { isLoading } = useLineChart();

	if (isLoading) return null;

	return (
		<ReferenceLine
			y={value}
			stroke={color}
			strokeDasharray="4 4"
			strokeOpacity={0.5}
			ifOverflow="extendDomain"
			label={
				label
					? {
							value: label,
							position: "insideRight",
							fill: color,
							fontSize: 10,
							// Sits below the line, with a little air between the two.
							dy: 12,
						}
					: undefined
			}
		/>
	);
}

type LegendProps = {
	variant?: ChartLegendVariant; // visual style of the legend indicators
	align?: "left" | "center" | "right"; // horizontal placement
	verticalAlign?: "top" | "middle" | "bottom"; // vertical placement
	isClickable?: boolean; // lets each entry toggle selection of its series
};

/**
 * The series legend. When `isClickable` is set, each entry toggles selection of
 * its series, driving the shared selection state read by every <Line />.
 */
export function Legend({
	variant,
	align = "right",
	verticalAlign = "top",
	isClickable = false,
}: LegendProps) {
	const { selectedDataKey, selectDataKey } = useLineChart();

	return (
		<ChartLegend
			verticalAlign={verticalAlign}
			align={align}
			content={
				<ChartLegendContent
					selected={selectedDataKey}
					onSelectChange={selectDataKey}
					isClickable={isClickable}
					variant={variant}
